import type { FilterDataStructure, FilterValue } from 'models/Filters';

import { getRegionOptionsForCountry } from '../../regionOptionsFromPreset';
import { FilterConfig } from '../types';

const REGION_BASELINE_VALUE = 'All';

function resolveRegionBaseline(filterData: FilterDataStructure): FilterValue {
  const def = filterData.region?.default?.value;
  return def != null && def !== '' ? def : REGION_BASELINE_VALUE;
}

function isRegionBaselineValue(
  filterData: FilterDataStructure,
  value: FilterValue,
): boolean {
  return String(value) === String(resolveRegionBaseline(filterData));
}

export const regionFilterConfig: FilterConfig = {
  key: 'region',
  order: 41,
  isCommon: true,
  parentKey: 'country',
  calculator: (filterData) => resolveRegionBaseline(filterData),
  dependentDefaultCascadingCalculator: (filterData) =>
    resolveRegionBaseline(filterData),
  validator: (filterData, value, currentApplied) => {
    if (isRegionBaselineValue(filterData, value)) return true;
    const list = getRegionOptionsForCountry(
      filterData,
      currentApplied?.country,
    );
    return list.some((o) => o.value === value);
  },
  contextualValidator: (dataFilters, country, region) => {
    if (isRegionBaselineValue(dataFilters, region)) return true;
    const list = getRegionOptionsForCountry(dataFilters, country);
    return list.some((o) => o.value === region);
  },
  metadata: {
    displayName: 'Region',
    description:
      'Commercial regions keyed by country. Baseline stays All until the user selects a region; country changes reset to All.',
  },
};
